<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Capabilities</title><link rel="stylesheet" href="{{ asset('css/app.css') }}"><style>*{box-sizing:border-box}.cp{min-height:100vh;padding:42px 5%;background:#f6f4ef}.cp-wrap{max-width:1000px;margin:auto}.cp-top{display:flex;justify-content:space-between;align-items:center;margin-bottom:25px}.cp-top h1{margin:0;font:700 38px Georgia}.cp-back{padding:12px 16px;border:1px solid #222;background:#fff;color:#111;text-decoration:none;font:700 13px Arial}.cp-card{padding:28px;background:#fff;border:1px solid #dfdad1;border-radius:9px}.cp-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.cp-field{display:flex;flex-direction:column;gap:8px}.cp-field.full{grid-column:1/-1}.cp-field label{font:700 14px Arial}.cp-field input,.cp-field textarea{width:100%;padding:13px;border:1px solid #cfc9be;border-radius:4px;font:15px Arial}.cp-field textarea{min-height:110px;resize:vertical}.cp-save{margin-top:24px;padding:15px 23px;border:0;background:#171717;color:#fff;font:700 14px Arial;cursor:pointer}.cp-success{padding:14px;background:#f3ede0;border-left:3px solid #9b7a40}.cp-list{margin-top:34px}.cp-list h2{font:700 28px Georgia}.cp-items{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.cp-item{padding:13px;background:#fff;border:1px solid #dfdad1}.cp-item img{width:100%;height:120px;object-fit:cover}.cp-item h3{margin:12px 0 6px;font:700 19px Georgia}.cp-item p{margin:0;font:14px/1.5 Arial}@media(max-width:650px){.cp-grid,.cp-items{grid-template-columns:1fr}.cp-field.full{grid-column:auto}.cp-top{align-items:flex-start;gap:15px;flex-direction:column}}</style></head><body><main class="cp"><div class="cp-wrap"><header class="cp-top"><h1>Capabilities</h1><a class="cp-back" href="{{ route('admin.dashboard') }}">← Back to dashboard</a></header>@if(session('success'))<p class="cp-success">{{ session('success') }}</p>@endif<form class="cp-card" 